// Check if current node has neighbors
if (current_node->neighbors.empty()) {
    current_node->find_neighbors();
}

for (auto neighbor : current_node->neighbors) {
    // Skip if neighbor is already visited
    if (neighbor->visited) {
        continue;
    }

    // Calculate g value (distance from start to current node + distance from current node to neighbor)
    float new_g_value = current_node->g_value + current_node->distance(*neighbor);

    // Check if neighbor is already in open list
    bool in_open_list = false;
    for (auto node : open_list) {
        if (node == neighbor) {
            in_open_list = true;
            // Update g value if new path is shorter
            if (new_g_value < node->g_value) {
                node->g_value = new_g_value;
            }
            break;
        }
    }

    // If neighbor is not in open list, add it
    if (!in_open_list) {
        neighbor->g_value = new_g_value;
        neighbor->h_value = calc_h_value(neighbor);
        open_list.push_back(neighbor);
    }
}

